    ctx.save();ctx.translate(465,238);ctx.rotate(-.08);ctx.fillStyle='#514a35';ctx.fillRect(-28,-26,56,52);ctx.fillStyle='#9b8052';ctx.fillRect(-25,-26,50,48);for(let x=-20;x<25;x+=9){ctx.fillStyle='#b79863';ctx.fillRect(x,-25,3,47);}ctx.restore();
  }
  function drawTree(t){const {x,y,r,t:kind}=t;ctx.fillStyle='#344a35';ctx.beginPath();ctx.ellipse(x+3,y+8,r*.8,r*.38,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#655c3e';ctx.fillRect(x-3,y-r*.05,7,r*.65);const colors=['#395c40','#426646','#4b7048','#36583d'];ctx.fillStyle=colors[Math.floor(kind*colors.length)];ctx.beginPath();ctx.arc(x,y-r*.34,r,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(x-r*.43,y-r*.2,r*.57,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(x+r*.42,y-r*.19,r*.59,0,Math.PI*2);ctx.fill();ctx.fillStyle='#6e8a53';ctx.globalAlpha=.55;ctx.beginPath();ctx.ellipse(x-r*.25,y-r*.59,r*.42,r*.19,-.4,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#a5b06a';ctx.fillRect(x-2,y-r*.48,3,2);}
  function drawHouse(){ctx.fillStyle='#3d4937';ctx.fillRect(735,523,86,59);ctx.fillStyle='#cab990';ctx.fillRect(741,516,76,57);ctx.fillStyle='#755541';path([[729,522],[779,485],[829,522]],'#68523b','#534633',3);ctx.fillStyle='#8c6846';ctx.fillRect(773,539,16,34);ctx.fillStyle='#dccb9e';ctx.fillRect(751,532,12,12);ctx.fillStyle='#758b78';ctx.fillRect(753,534,8,8);ctx.fillStyle='#e2ce9b';ctx.fillRect(798,532,12,12);ctx.fillStyle='#758b78';ctx.fillRect(800,534,8,8);ctx.fillStyle='#d0b77e';ctx.fillRect(779,539,2,34);}
  function drawNpc(){const x=npc.x,y=npc.y;ctx.fillStyle='#3e4935';ctx.beginPath();ctx.ellipse(x,y+11,12,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#537459';ctx.fillRect(x-8,y-7,16,17);ctx.fillStyle='#d8b990';ctx.fillRect(x-6,y-18,12,12);ctx.fillStyle='#e2d4b8';ctx.fillRect(x-8,y-20,16,5);ctx.fillStyle='#697a50';ctx.fillRect(x-9,y-22,18,4);ctx.fillStyle='#403b2e';ctx.fillRect(x-3,y-13,2,2);ctx.fillRect(x+3,y-13,2,2);if(Math.hypot(player.x-x,player.y-y)<100){ctx.fillStyle='#f0e2b9';ctx.font='11px Manrope';ctx.textAlign='center';ctx.fillText('Don Eusebio',x,y-30);ctx.fillStyle='#d8c477';ctx.font='12px serif';ctx.fillText('✦',x,y-40);}}
  function drawSlime(s){if(!s.alive)return;const x=s.x,y=s.y;ctx.fillStyle='#34463580';ctx.beginPath();ctx.ellipse(x,y+8,15,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=s.hit>0?'#dca987':'#8ba16a';ctx.beginPath();ctx.ellipse(x,y,13,11,0,Math.PI,Math.PI*2);ctx.lineTo(x+13,y+4);ctx.quadraticCurveTo(x,y+13,x-13,y+4);ctx.fill();ctx.fillStyle='#aabd7d';ctx.beginPath();ctx.ellipse(x-4,y-5,5,2,-.4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#34433b';ctx.fillRect(x-5,y-1,2,3);ctx.fillRect(x+4,y-1,2,3);ctx.fillStyle='#fff';ctx.fillRect(x-5,y-2,1,1);ctx.fillRect(x+4,y-2,1,1);if(s.hp<s.max||s.aggro){ctx.fillStyle='#26382e';ctx.fillRect(x-16,y-20,32,4);ctx.fillStyle='#b76f5d';ctx.fillRect(x-15,y-19,30*(s.hp/s.max),2);}}
  function drawPlayer(){const {x,y,dir,attacking}=player;ctx.fillStyle='#3042338c';ctx.beginPath();ctx.ellipse(x,y+12,14,6,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#536d58';ctx.fillRect(x-9,y-6,18,18);ctx.fillStyle='#7b9b74';ctx.fillRect(x-8,y-5,5,14);ctx.fillStyle='#c4ab7f';ctx.fillRect(x-6,y-18,12,12);ctx.fillStyle='#4c4735';ctx.fillRect(x-7,y-21,14,5);ctx.fillStyle='#c3ad76';ctx.fillRect(x-8,y-19,16,2);ctx.fillStyle='#27342c';ctx.fillRect(x+dir*3,y-13,2,2);ctx.fillStyle='#756344';ctx.fillRect(x-4,y+11,4,5);ctx.fillRect(x+3,y+11,4,5);if(attacking>0){ctx.strokeStyle='#f3df9b';ctx.lineWidth=3;ctx.beginPath();ctx.arc(x+dir*9,y,23,dir===1?-.9:Math.PI-.9,dir===1?.9:Math.PI+.9);ctx.stroke();ctx.fillStyle='#d5c18d';ctx.fillRect(x+dir*13-1,y-14,3,18);}}

function draw(){const rect=canvas.getBoundingClientRect(),w=rect.width,h=rect.height;if(!w||!h)return;ctx.clearRect(0,0,w,h);ctx.save();ctx.translate(w/2,h/2);ctx.scale(state.zoom,state.zoom);ctx.translate(-state.camera.x,-state.camera.y);drawGround(w,h);
