  drawHouse();const things=[...trees.filter(t=>Math.abs(t.x-state.camera.x)<w/state.zoom/2+80&&Math.abs(t.y-state.camera.y)<h/state.zoom/2+80).map(t=>({y:t.y,draw:()=>drawTree(t)})),{y:npc.y,draw:drawNpc},...state.slimes.map(s=>({y:s.y,draw:()=>drawSlime(s)})),{y:player.y,draw:drawPlayer}].sort((a,b)=>a.y-b.y);for(const thing of things)thing.draw();
  // Selection ring makes clickable targets obvious.
  const selected=state.slimes.find(s=>s.id===state.selected&&s.alive);if(selected){ctx.strokeStyle='#e7d18b';ctx.lineWidth=1.5;ctx.beginPath();ctx.ellipse(selected.x,selected.y+8,19,6,0,0,Math.PI*2);ctx.stroke();}
  ctx.restore();}
function updateNearby(){const nearby=state.slimes.filter(s=>s.alive&&Math.hypot(s.x-player.x,s.y-player.y)<560).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y)).slice(0,3);$('nearbyNum').textContent=nearby.length;$('nearbyList').innerHTML=nearby.length?nearby.map(s=>`<div class="nearby-entity" data-target="${s.id}"><span class="entity-avatar monster">◉</span><span class="entity-meta"><b>Limo verde</b><small>${Math.round(Math.hypot(s.x-player.x,s.y-player.y))} pasos · Nivel 1</small></span><span class="entity-health"><i style="width:${100*s.hp/s.max}%"></i></span><span class="entity-chevron">›</span></div>`).join(''):'<p style="font-size:9px;color:#999;margin:12px 0">No hay criaturas cerca.</p>';}
function updateMinimap(){const dot=document.querySelector('.player-dot');dot.style.left=`${clamp(player.x/WORLD.w*100,2,96)}%`;dot.style.top=`${clamp(player.y/WORLD.h*100,2,94)}%`;const c=state.camera;$('coords').textContent=`X: ${String(Math.round(player.x/20)).padStart(3,'0')} · Y: ${String(Math.round(player.y/20)).padStart(3,'0')}`;}
function update(t){if(!state.started||state.paused)return;const dt=Math.min(.04,(t-state.last)/1000||0);state.last=t;state.time+=dt;
  let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);
  if(state.moveTarget&&!dx&&!dy){dx=state.moveTarget.x-player.x;dy=state.moveTarget.y-player.y;if(Math.hypot(dx,dy)<8)state.moveTarget=null;else{const d=Math.hypot(dx,dy);dx/=d;dy/=d;}}
  if(dx||dy){const d=Math.hypot(dx,dy);dx/=d;dy/=d;player.x=clamp(player.x+dx*125*dt,18,WORLD.w-18);player.y=clamp(player.y+dy*125*dt,18,WORLD.h-18);if(Math.abs(dx)>.1)player.dir=Math.sign(dx);player.stam=Math.max(0,player.stam-5*dt);}else player.stam=Math.min(100,player.stam+9*dt);
  for(const s of state.slimes){if(!s.alive)continue;s.hit=Math.max(0,(s.hit||0)-dt*4);s.attack=Math.max(0,s.attack-dt);const d=Math.hypot(player.x-s.x,player.y-s.y);if(d<200)s.aggro=true;if(s.aggro&&d<265){if(d>31){s.x+=(player.x-s.x)/d*48*dt;s.y+=(player.y-s.y)/d*48*dt;}else if(s.attack<=0){s.attack=1.6;player.hp=Math.max(0,player.hp-5);addLog('Un limo verde te golpea.');notify('El limo te golpeó · −5 vida');if(player.hp<=0)fall();}}else if(d>320)s.aggro=false;else if(!s.aggro){s.x+=Math.sin(state.time*.8+s.id)*5*dt;s.y+=Math.cos(state.time*.7+s.id)*4*dt;}}
  const cam=state.camera;cam.x+=(player.x-cam.x)*Math.min(1,dt*4);cam.y+=(player.y-cam.y)*Math.min(1,dt*4);if(state.player.attacking>0)state.player.attacking=Math.max(0,state.player.attacking-dt);updateHUD();updateMinimap();draw();requestAnimationFrame(update);
}
function fall(){player.hp=100;player.x=780;player.y=660;state.camera.x=player.x;state.camera.y=player.y;state.slimes.forEach(s=>{s.aggro=false;s.x=s.homeX;s.y=s.homeY});notify('Despertaste en Ullathorpe · vida restaurada');addLog('Don Eusebio te llevó de vuelta a la aldea.');}
function gainXP(amount){player.xp+=amount;while(player.xp>=player.level*100){player.xp-=player.level*100;player.level++;player.hp=100;player.mp=40;notify(`¡Subiste al nivel ${player.level}!`);addLog(`¡Alcanzaste el nivel ${player.level}!`,'log-quest');}updateHUD();}
function attack(){if(!state.started)return;const now=performance.now();if(now-state.attackAt<430)return;state.attackAt=now;player.attacking=.23;let target=state.slimes.find(s=>s.id===state.selected&&s.alive);if(!target||Math.hypot(target.x-player.x,target.y-player.y)>80)target=state.slimes.filter(s=>s.alive&&Math.hypot(s.x-player.x,s.y-player.y)<78).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0];if(!target){notify('Acercate a un limo para atacar');return;}state.selected=target.id;state.moveTarget=null;const d=Math.hypot(target.x-player.x,target.y-player.y);if(d>43){const vx=(target.x-player.x)/d,vy=(target.y-player.y)/d;player.x+=vx*Math.min(22,d-36);player.y+=vy*Math.min(22,d-36);}target.hp-=Math.round(12+Math.random()*5);target.hit=.3;player.mp=Math.max(0,player.mp-1);if(target.hp<=0){target.alive=false;state.questKills++;player.gold+=4;gainXP(28);addLog('Derrotaste un limo verde. +28 XP · +4 oro','log-quest');notify('Limo derrotado · +28 XP · +4 oro');if(state.questKills===3&&!state.questDone){addLog('Objetivo cumplido: volvé con Don Eusebio.','log-quest');notify('¡Misión cumplida! Volvé con Don Eusebio.');}if(state.questKills>=3)state.slimes=state.slimes.filter(s=>s.alive||s.id!==target.id);}else{addLog(`Golpeaste al limo verde. (${Math.max(0,target.hp)} vida)`);notify(`¡Golpe! El limo tiene ${target.hp} de vida.`);}updateHUD();}
function usePotion(type){if(type==='hp'){if(!player.potions){notify('No te quedan pociones de vida');return;}if(player.hp>=100){notify('Tu vida ya está completa');return;}player.potions--;player.hp=Math.min(100,player.hp+45);notify('Poción de vida · +45 ❤️');addLog('Tomaste una poción de vida.');}else{if(!player.manas){notify('No te quedan pociones de maná');return;}if(player.mp>=40){notify('Tu maná ya está completo');return;}player.manas--;player.mp=Math.min(40,player.mp+25);notify('Poción de maná · +25 ✦');addLog('Tomaste una poción de maná.');}updateHUD();}
const backdrop=$('modalBackdrop'),content=$('modalContent');
function openModal(html){state.paused=true;content.innerHTML=html;backdrop.classList.add('show');}
function closeModal(){backdrop.classList.remove('show');state.paused=false;state.last=performance.now();}
function talk(){const d=Math.hypot(player.x-npc.x,player.y-npc.y);if(d>95){notify('Acercate a Don Eusebio');state.moveTarget={x:npc.x,y:npc.y+33};return;}if(state.questKills>=3&&!state.questDone){openModal(`<p class="eyebrow">DON EUSEBIO · ULLATHORPE</p><h2>¡El camino está libre!</h2><p>¡Lo lograste, aventurero! Ya no hay limos merodeando el camino. La aldea te debe una.</p><p style="color:#927e4f">Recompensa: 80 XP · 35 oro · 2 pociones de vida</p><div class="dialog-buttons"><button class="primary" id="claimReward">COBRAR RECOMPENSA</button><button id="modalDismiss">MÁS TARDE</button></div>`);$('claimReward').onclick=()=>{state.questDone=true;player.gold+=35;player.potions+=2;gainXP(80);closeModal();$('questCount').textContent='COMPLETADA';$('questCount').style.color='#66845a';addLog('Misión completada: Una plaga verde. +80 XP · +35 oro','log-quest');notify('Misión completada · +35 oro · +2 pociones');};$('modalDismiss').onclick=closeModal;return;}if(state.questDone){openModal(`<p class="eyebrow">DON EUSEBIO · ULLATHORPE</p><h2>Siempre bienvenido.</h2><p>La aldea está en deuda con vos. Descansá junto al fuego; el camino hacia el sur siempre guarda nuevas historias.</p><div class="dialog-buttons"><button class="primary" id="modalDismiss">HASTA LUEGO</button></div>`);$('modalDismiss').onclick=closeModal;return;}openModal(`<p class="eyebrow">DON EUSEBIO · ULLATHORPE</p><h2>¡Qué bueno que llegaste!</h2><p>Los limos verdes están invadiendo el camino. ¿Podrías derrotar a tres de ellos? Te recompensaré como corresponde.</p><p style="color:#927e4f">Recompensa: 80 XP · 35 oro · 2 pociones de vida</p><div class="dialog-buttons"><button class="primary" id="acceptQuest">ACEPTAR ENCARGO</button><button id="modalDismiss">DESPUÉS</button></div>`);$('acceptQuest').onclick=()=>{closeModal();notify('Encargo aceptado · derrotá 3 limos');addLog('Aceptaste el encargo de Don Eusebio.','log-quest');};$('modalDismiss').onclick=closeModal;}
function showInventory(){openModal(`<p class="eyebrow">TUS PERTENENCIAS</p><h2>Inventario</h2><p>Lo que llevás con vos en esta aventura.</p><div class="inventory-grid"><div class="inventory-slot">⚔<small>ESPADA CORTA</small></div><div class="inventory-slot">♜<small>TÚNICA DE CUERO</small></div><div class="inventory-slot">🧪<small>POCIÓN × ${player.potions}</small></div><div class="inventory-slot">🔵<small>MANÁ × ${player.manas}</small></div><div class="inventory-slot">◈<small>${player.gold} ORO</small></div><div class="inventory-slot">✦<small>MAPA VIEJO</small></div></div><div class="dialog-buttons"><button class="primary" id="modalDismiss">CERRAR</button></div>`);$('modalDismiss').onclick=closeModal;}
function showHelp(){openModal(`<p class="eyebrow">GUÍA DEL AVENTURERO</p><h2>Cómo jugar</h2><p>Explorá el bosque, ayudá a sus habitantes y convertite en leyenda. El mundo es tuyo.</p><div class="help-list"><span><kbd>W A S D</kbd> Moverte por el bosque</span><span><kbd>CLIC</kbd> Caminar / elegir objetivo</span><span><kbd>ESPACIO</kbd> Atacar al enemigo cercano</span><span><kbd>E</kbd> Hablar con Don Eusebio</span><span><kbd>H</kbd> Poción de vida</span><span><kbd>J</kbd> Poción de maná</span></div><div class="dialog-buttons"><button class="primary" id="modalDismiss">¡A LA AVENTURA!</button></div>`);$('modalDismiss').onclick=closeModal;}

