  canvas.addEventListener('contextmenu',e=>{e.preventDefault();attack();});
  window.addEventListener('keydown',e=>{if(e.target.matches('input,textarea'))return;const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='escape'){if(backdrop.classList.contains('show'))closeModal();else $('mapOverlay').classList.remove('show');return;}if(k==='e'){talk();return;}if(k===' '){attack();return;}if(k==='h'){usePotion('hp');return;}if(k==='j'){usePotion('mp');return;}if(k==='i'){showInventory();return;}keys.add(k);});
  window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());
  window.addEventListener('beforeunload',save);setInterval(save,5000);
  draw();updateNearby();requestAnimationFrame(update);
})();

